/**
 * Canonical serialization: object keys sorted, integers only for numbers, no undefined. Two equal states always
 * serialize to the same string, whatever order their keys were written in.
 */
export function canonicalize(value: unknown): string {
  if (value === null) return "null";
  switch (typeof value) {
    case "number":
      if (!Number.isSafeInteger(value)) throw new TypeError(`state numbers must be safe integers, got ${value}`);
      return String(value);
    case "string":
      return JSON.stringify(value);
    case "boolean":
      return value ? "true" : "false";
    case "object": {
      if (Array.isArray(value)) return `[${value.map(canonicalize).join(",")}]`;
      const prototype = Object.getPrototypeOf(value);
      if (prototype !== Object.prototype && prototype !== null) throw new TypeError("state must be plain data");
      const entries = Object.keys(value)
        .sort()
        .filter((key) => (value as Record<string, unknown>)[key] !== undefined)
        .map((key) => `${JSON.stringify(key)}:${canonicalize((value as Record<string, unknown>)[key])}`);
      return `{${entries.join(",")}}`;
    }
    default:
      throw new TypeError(`state cannot hold a ${typeof value}`);
  }
}

const FNV_OFFSET = 0xcbf29ce484222325n;
const FNV_PRIME = 0x100000001b3n;
const MASK_64 = 0xffffffffffffffffn;

/** 64-bit FNV-1a over the UTF-16 code units of a string, as 16 hex digits. */
export function fnv1a64(text: string): string {
  let hash = FNV_OFFSET;
  for (let index = 0; index < text.length; index++) {
    const unit = text.charCodeAt(index);
    hash = ((hash ^ BigInt(unit & 0xff)) * FNV_PRIME) & MASK_64;
    hash = ((hash ^ BigInt(unit >>> 8)) * FNV_PRIME) & MASK_64;
  }
  return hash.toString(16).padStart(16, "0");
}

/** A stable hash of the complete match state, independent of JavaScript engine and key order. */
export function hashState(state: unknown): string {
  return fnv1a64(canonicalize(state));
}
import { HEADING_COUNT } from "@pirate-sea-race/content";

/** Unit vectors are scaled by this: a heading's x and y components are integers in [-1024, 1024]. */
export const HEADING_SCALE = 1024;

/**
 * cos(2π·i/64)·1024 rounded, for the first quarter turn (i = 0…16). Written out as data so that no floating-point
 * transcendental function runs in the simulation; the other three quarters follow by symmetry.
 */
const QUARTER_COSINES: readonly number[] = [1024, 1019, 1004, 980, 946, 903, 851, 792, 724, 650, 569, 483, 392, 297, 200, 100, 0];

const QUARTER = HEADING_COUNT / 4;

function cosine(heading: number): number {
  const turn = normalizeHeading(heading);
  if (turn <= QUARTER) return QUARTER_COSINES[turn]!;
  // Subtracting from 0 rather than negating keeps the table free of -0.
  if (turn <= 2 * QUARTER) return 0 - QUARTER_COSINES[2 * QUARTER - turn]!;
  if (turn <= 3 * QUARTER) return 0 - QUARTER_COSINES[turn - 2 * QUARTER]!;
  return QUARTER_COSINES[HEADING_COUNT - turn]!;
}

/** Heading components: DX[h], DY[h]. Heading 0 is east; y grows down, so headings count clockwise on screen. */
export const HEADING_DX: readonly number[] = Array.from({ length: HEADING_COUNT }, (_, heading) => cosine(heading));
export const HEADING_DY: readonly number[] = Array.from({ length: HEADING_COUNT }, (_, heading) => cosine(heading - QUARTER));

export function normalizeHeading(heading: number): number {
  return ((heading % HEADING_COUNT) + HEADING_COUNT) % HEADING_COUNT;
}
/**
 * A seeded 32-bit generator (mulberry32). Its whole state is one unsigned integer kept in the match state, so a
 * snapshot restores the random sequence exactly.
 */
export function nextRandom(state: number): { value: number; state: number } {
  const next = (state + 0x6d2b79f5) >>> 0;
  let t = next;
  t = Math.imul(t ^ (t >>> 15), t | 1);
  t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
  return { value: (t ^ (t >>> 14)) >>> 0, state: next };
}

/** An integer in [0, bound), for bounds up to 2^32. The modulo bias is negligible for the small bounds used here. */
export function nextInt(state: number, bound: number): { value: number; state: number } {
  if (!Number.isInteger(bound) || bound <= 0) throw new RangeError(`bound must be a positive integer, got ${bound}`);
  const drawn = nextRandom(state);
  return { value: drawn.value % bound, state: drawn.state };
}

