/** Steps recorded inputs without reacting to anything. */
function replay(config: EncounterConfig, inputs: readonly EncounterTickInput[], spawnProtected: readonly string[]): Run {
  let state = createEncounterState(config, { spawnProtected });
  const states: EncounterState[] = [];
  const events: EncounterEvent[][] = [];
  for (const input of inputs) {
    const stepped = stepEncounters(config, state, input);
    state = stepped.state;
    states.push(state);
    events.push([...stepped.events]);
  }
  return { inputs, states, hashes: states.map(hashState), events };
}

const spawnProtectedOf = (run: Run) => (run.states.length === 0 ? [] : createInitial(run));
/** The spawn-protected ids are not in the inputs; recover them from the first state and events. */
function createInitial(run: Run): string[] {
  const first = run.states[0]!;
  const ended = run.events[0]!.filter((event) => event.kind === "protection-ended").map((event) => (event as { playerId: string }).playerId);
  return [...first.players.filter((player) => player.protection?.source === "spawn").map((player) => player.id), ...ended].sort();
